import { createRequire } from "module";
  const require = createRequire(import.meta.url);

// src/app.ts
import express from "express";
import cookieParser from "cookie-parser";
import cors from "cors";
import helmet from "helmet";
import pino from "pino-http";

// src/config/index.ts
import dotenv from "dotenv";
import path from "path";
dotenv.config({ path: path.join(process.cwd() + ".env") });
var config = {
  port: process.env.PORT,
  database_url: process.env.DATABASE_URL,
  frontend_url_dev: process.env.FRONTEND_URL_DEV,
  node_env: process.env.NODE_ENV
};

// src/utils/sendResponse.ts
var sendResponse = (res, data) => {
  const statusCode = data.statusCode || 500;
  res.status(statusCode).json({
    success: data.success,
    message: data.message || "Internal Server Error!",
    statusCode,
    data: data.data,
    meta: data.meta
  });
};

// src/middlewares/notFound.ts
var notFound = (req, res) => {
  sendResponse(res, {
    success: false,
    message: "Route Not Found!",
    statusCode: 404
  });
};

// src/routes/index.ts
import { Router as Router2 } from "express";

// src/modules/auth/auth.routes.ts
import { Router } from "express";

// src/modules/auth/auth.service.ts
var registerUserOnDB = async (payload) => {
  return await payload;
};
var AuthServices = {
  registerUserOnDB
};

// src/modules/auth/auth.controller.ts
var registerUser = async (req, res) => {
  const authInfo = req.body;
  const result = await AuthServices.registerUserOnDB(authInfo);
  sendResponse(res, {
    statusCode: 200,
    message: "User Registered Successfully!",
    success: true,
    data: result
  });
};
var AuthControllers = {
  registerUser
};

// src/middlewares/multer.ts
import multer from "multer";
var upload = multer({
  storage: multer.memoryStorage()
});
var multer_default = upload;

// src/modules/auth/auth.routes.ts
var router = Router();
router.post("/register", multer_default.none(), AuthControllers.registerUser);
var authRoutes = router;

// src/routes/index.ts
var router2 = Router2();
router2.use("/auth", authRoutes);
var routes_default = router2;

// src/app.ts
var app = express();
app.use(helmet());
app.use(
  cors({
    origin: [config.frontend_url_dev]
  })
);
app.use(
  pino({
    redact: [
      "req.headers.authorization",
      "req.headers.cookie",
      "res.headers.set-cookie"
    ]
  })
);
app.use(express.json({ limit: "1mb" }));
app.use(
  express.urlencoded({
    extended: true
  })
);
app.use(cookieParser());
app.get("/", (req, res) => {
  res.send("Welcome to CCL E-commerce server!");
});
app.get("/api/v1", (req, res) => {
  res.send("Welcome to CCL E-commerce server version 1 is boosted on\u{1F525}\u{1F525}!");
});
app.use("/api/v1", routes_default);
app.use(notFound);
var app_default = app;

